import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const Profile = () => {
  const { user } = useAuth();
  const [lastVisit, setLastVisit] = useState(null);
  const [activeTab, setActiveTab] = useState('overview');

  useEffect(() => {
    const visit = localStorage.getItem('lastVisit');
    if (visit) {
      setLastVisit(new Date(visit).toLocaleString());
    }
  }, []);

  return (
    <div>
      <div className="profile-hero card mb-4">
        <div className="card-body">
          <div className="d-flex flex-column flex-md-row align-items-start gap-4">
            <div className="profile-avatar">{user?.name?.charAt(0)}</div>
            <div className="profile-hero-copy">
              <span className="profile-hero-pill">💼 My Profile</span>
              <h2 className="mb-2">Welcome back, {user?.name || 'there'}!</h2>
              <p className="text-muted mb-0">
                This space shows your profile details, account status, and quick access to secure settings in one glowing panel.
              </p>
            </div>
            <div className="ms-auto text-end">
              <span className={`status-pill ${user?.role === 'admin' ? 'admin' : 'active'}`}>Active</span>
              <p className="text-muted small mt-2 mb-0">Role: {user?.role}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="profile-tabs" role="tablist" aria-label="Profile tabs">
        <button
          type="button"
          className={`profile-tab ${activeTab === 'overview' ? 'active' : ''}`}
          onClick={() => setActiveTab('overview')}
          role="tab"
          aria-selected={activeTab === 'overview'}
        >
          Overview
        </button>
        <button
          type="button"
          className={`profile-tab ${activeTab === 'security' ? 'active' : ''}`}
          onClick={() => setActiveTab('security')}
          role="tab"
          aria-selected={activeTab === 'security'}
        >
          Security
        </button>
      </div>

      <div className="profile-panel" role="tabpanel">
        {activeTab === 'overview' && (
          <div className="profile-section">
            <div className="row gy-4">
              <div className="col-lg-7">
                <div className="card profile-card">
                  <div className="card-body">
                    <h5 className="card-title">Profile Information</h5>
                    <table className="table profile-info-table mb-0">
                      <tbody>
                        <tr>
                          <th>Name:</th>
                          <td>{user?.name || '—'}</td>
                        </tr>
                        <tr>
                          <th>Email:</th>
                          <td>{user?.email || '—'}</td>
                        </tr>
                        <tr>
                          <th>Role:</th>
                          <td>
                            <span className={`status-pill ${user?.role === 'admin' ? 'admin' : 'active'}`}>
                              {user?.role}
                            </span>
                          </td>
                        </tr>
                        <tr>
                          <th>Account Status:</th>
                          <td><span className="status-pill active">Active</span></td>
                        </tr>
                        <tr>
                          <th>User ID:</th>
                          <td>{user?.id || '—'}</td>
                        </tr>
                        <tr>
                          <th>Last Visit:</th>
                          <td>{lastVisit || 'First time visit'}</td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>

              <div className="col-lg-5">
                <div className="summary-grid">
                  <div className="summary-card">
                    <p className="text-muted mb-1">Preferred Theme</p>
                    <h5 className="mb-0">Light</h5>
                  </div>
                  <div className="summary-card">
                    <p className="text-muted mb-1">Notifications</p>
                    <h5 className="mb-0">Enabled</h5>
                  </div>
                  <div className="summary-card">
                    <p className="text-muted mb-1">Member Since</p>
                    <h5 className="mb-0">2024</h5>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'security' && (
          <div className="profile-section">
            <div className="card profile-card">
              <div className="card-body">
                <h5 className="card-title">Security Settings</h5>
                <div className="row gx-4 gy-4">
                  <div className="col-md-6">
                    <div className="security-block">
                      <p className="text-muted mb-1">Password Strength</p>
                      <strong>Strong</strong>
                    </div>
                    <div className="security-block">
                      <p className="text-muted mb-1">Two-factor Authentication</p>
                      <strong>Disabled</strong>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="security-block">
                      <p className="text-muted mb-1">Login Alerts</p>
                      <strong>On</strong>
                    </div>
                    <div className="security-block">
                      <p className="text-muted mb-1">Recent Access</p>
                      <strong>{lastVisit || 'First time visit'}</strong>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Profile;
