import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

const Settings = () => {
  const navigate = useNavigate();
  const { theme, toggleTheme, user } = useAuth();
  const [notifications, setNotifications] = useState(() => {
    const saved = localStorage.getItem('notifications');
    return saved === 'true';
  });
  const [emailAlerts, setEmailAlerts] = useState(() => {
    const saved = localStorage.getItem('emailAlerts');
    return saved === 'true';
  });
  const [language, setLanguage] = useState(() => {
    return localStorage.getItem('language') || 'en';
  });

  useEffect(() => {
    localStorage.setItem('notifications', notifications);
  }, [notifications]);

  useEffect(() => {
    localStorage.setItem('emailAlerts', emailAlerts);
  }, [emailAlerts]);

  useEffect(() => {
    localStorage.setItem('language', language);
  }, [language]);

  const handleNotificationsToggle = () => {
    const newValue = !notifications;
    setNotifications(newValue);
    toast.success(newValue ? 'Notifications enabled' : 'Notifications disabled');
  };

  const handleEmailAlertsToggle = () => {
    const newValue = !emailAlerts;
    setEmailAlerts(newValue);
    toast.success(newValue ? 'Email alerts enabled' : 'Email alerts disabled');
  };

  const handleLanguageChange = (e) => {
    const newLang = e.target.value;
    setLanguage(newLang);
    toast.success(`Language changed to ${newLang === 'en' ? 'English' : 'Русский'}`);
  };

  const resetAllSettings = () => {
    if (window.confirm('Are you sure you want to reset all settings? This cannot be undone.')) {
      setNotifications(false);
      setEmailAlerts(false);
      setLanguage('en');

      localStorage.removeItem('notifications');
      localStorage.removeItem('emailAlerts');
      localStorage.removeItem('language');

      toast.success('All settings reset to default');

      setTimeout(() => {
        window.location.reload();
      }, 1000);
    }
  };

  return (
    <div>
      <div className="settings-hero card mb-4">
        <div className="card-body">
          <div className="d-flex flex-column flex-md-row align-items-start gap-4">
            <div>
              <span className="settings-label">⚙️ Settings</span>
              <h2 className="mb-2">Fine-tune your dashboard vibe</h2>
              <p className="text-muted mb-0">
                Choose theme mood, notification behavior, and language preferences in a playful control center.
              </p>
            </div>
            <div className="ms-auto settings-hero-status text-end">
              <span className={`status-pill ${theme === 'light' ? 'active' : 'dark'}`}>
                {theme === 'light' ? 'Light mode' : 'Dark mode'}
              </span>
              <p className="text-muted small mb-0 mt-2">Currently applied theme</p>
            </div>
          </div>
        </div>
      </div>

      <div className="settings-grid">
        <div className="settings-panel">
          <div className="settings-panel-header">
            <h5>🎨 Appearance</h5>
            <span className="settings-chip">Theme</span>
          </div>
          <div className="settings-panel-body">
            <p className="text-muted">Switch between sunlit and night mode with style.</p>
            <button
              onClick={toggleTheme}
              className="btn btn-primary btn-shadow"
            >
              {theme === 'light' ? '🌙 Darken the interface' : '☀️ Brighten the interface'}
            </button>
          </div>
        </div>

        <div className="settings-panel">
          <div className="settings-panel-header">
            <h5>🔔 Notifications</h5>
            <span className="settings-chip">Alerts</span>
          </div>
          <div className="settings-panel-body">
            <div className="form-check form-switch mb-3">
              <input
                className="form-check-input"
                type="checkbox"
                id="notificationsSwitch"
                checked={notifications}
                onChange={handleNotificationsToggle}
              />
              <label className="form-check-label" htmlFor="notificationsSwitch">
                Push notifications
              </label>
            </div>

            <div className="form-check form-switch mb-3">
              <input
                className="form-check-input"
                type="checkbox"
                id="emailAlertsSwitch"
                checked={emailAlerts}
                onChange={handleEmailAlertsToggle}
              />
              <label className="form-check-label" htmlFor="emailAlertsSwitch">
                Email alerts
              </label>
            </div>

            <p className="text-muted small mt-2">
              Smart alerts help you stay informed without losing focus.
            </p>
          </div>
        </div>

        <div className="settings-panel settings-panel-accent">
          <div className="settings-panel-header">
            <h5>🌐 Language</h5>
            <span className="settings-chip">Locale</span>
          </div>
          <div className="settings-panel-body">
            <select
              className="form-select"
              value={language}
              onChange={handleLanguageChange}
            >
              <option value="en">English 🇺🇸</option>
              <option value="ru">Русский 🇷🇺</option>
            </select>
            <p className="text-muted small mt-2">
              {language === 'en' ? 'Interface language preference' : 'Предпочтительный язык интерфейса'}
            </p>
          </div>
        </div>

        <div className="settings-panel settings-panel-info">
          <div className="settings-panel-header">
            <h5>👤 Account</h5>
            <span className="settings-chip">Profile</span>
          </div>
          <div className="settings-panel-body">
            <p><strong>Name:</strong> {user?.name}</p>
            <p><strong>Email:</strong> {user?.email}</p>
            <p><strong>Role:</strong> <span className={`status-pill ${user?.role === 'admin' ? 'admin' : 'active'}`}>{user?.role}</span></p>
          </div>
        </div>

        <div className="settings-panel settings-panel-warning">
          <div className="settings-panel-header">
            <h5>⚠️ Reset</h5>
            <span className="settings-chip">Danger zone</span>
          </div>
          <div className="settings-panel-body">
            <p className="text-muted">Reset your dashboard preferences and clean the cache of saved options.</p>
            <button
              className="btn btn-danger btn-shadow"
              onClick={resetAllSettings}
            >
              Reset all settings
            </button>
          </div>
        </div>
      </div>

      <div className="mt-3">
        <button
          onClick={() => navigate(-1)}
          className="btn btn-outline-secondary"
        >
          ← Back
        </button>
      </div>
    </div>
  );
};

export default Settings;
